(() => {
  const canvas = document.getElementById('world');
  const ctx = canvas.getContext('2d');
  const mini = document.getElementById('minimap');
  const mctx = mini.getContext('2d');
  const $ = id => document.getElementById(id);
  const classes = {
    Swordsman: { icon:'⚔', stats:[10,8,5,12], hp:120, mana:60, damage:18, color:'#bfc394', skill:'Shieldbreak' },
    Wizard: { icon:'✧', stats:[5,7,12,8], hp:90, mana:130, damage:23, color:'#a5c5ce', skill:'Arcane bolt' },
    Ninja: { icon:'◈', stats:[8,14,7,7], hp:95, mana:80, damage:21, color:'#c8958c', skill:'Shadowstep' },
    Archer: { icon:'➶', stats:[9,12,6,8], hp:100, mana:75, damage:19, color:'#b7c98e', skill:'Piercing shot' }
  };
  const rarityNames=['Common','Uncommon','Rare','Mythic','Legendary','Ancient','Celestial'];
  const rarityColors=['#a5ad9b','#78b28c','#72a8d1','#b58bd3','#d8b456','#e08a63','#e8d789'];
  const gear={Swordsman:['Verdant Edge','Brambleguard','Wayfarer’s Signet'],Wizard:['Mossglass Wand','Whisperweave','Aetherleaf Charm'],Ninja:['Duskleaf Knives','Shadecloth Wraps','Foxfire Talisman'],Archer:['Wildwood Longbow','Ranger’s Mantle','Hawkeye Brooch']};
  let W=900,H=560,dpr=1,selectedClass='Swordsman',target=0,toastTimer=0,paused=true,showMap=false,questKills=0,attackFlash=0;
  let player={x:0,y:0,level:1,xp:0,stats:[10,8,5,12],statPoints:0,skillPoints:0,maxHp:120,hp:120,maxMana:60,mana:60,potions:3,gold:24,items:[],name:'Aeron Vale'};
  let mobs=[];let lastTime=0;let autosaveAt=0;const keys=new Set();
  const rand=(a,b)=>a+Math.random()*(b-a);
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function levelXP(level){return Math.floor(100*Math.pow(level,1.12));}
  function mobLevel(){return Math.max(1,player.level+Math.floor(rand(-1,2)));}
  function makeMob(x,y){const level=mobLevel();return {x,y,level,maxHp:Math.floor(70+level*21),hp:Math.floor(70+level*21),name:['Mossback Grazer','Thornling','Glimmerfox','Briarling','Mossback Grazer'][Math.floor(Math.random()*5)],type:['VERDANT BEAST','WILD SPIRIT','FRONTIER CREATURE'][Math.floor(Math.random()*3)],attackAt:0,respawn:0,seed:rand(0,8),alive:true};}
  function initMobs(){mobs=[];for(let i=0;i<5;i++)mobs.push(makeMob(rand(W*.18,W*.82),rand(H*.28,H*.72)));}
  function resize(){const r=canvas.getBoundingClientRect();if(!r.width||!r.height)return;W=r.width;H=r.height;dpr=Math.min(window.devicePixelRatio||1,2);canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0);if(!player.x){player.x=W*.49;player.y=H*.65;}if(!mobs.length)initMobs();drawMini();}
  function terrain(){
    const g=ctx.createLinearGradient(0,0,0,H);g.addColorStop(0,'#63704a');g.addColorStop(.4,'#596741');g.addColorStop(1,'#324735');ctx.fillStyle=g;ctx.fillRect(0,0,W,H);
    // soft forest light
    const glow=ctx.createRadialGradient(W*.53,H*.31,10,W*.53,H*.31,W*.7);glow.addColorStop(0,'#c7c78126');glow.addColorStop(1,'#121d142b');ctx.fillStyle=glow;ctx.fillRect(0,0,W,H);
    // distant canopy silhouettes
    for(let i=0;i<24;i++){let x=i*W/20-(W*.1),y=rand;let yy=22+((i*37)%77);const r=22+(i*19%27);treeTop(x,yy,r,'#344a36',.65);}
    // winding pale trail
    ctx.save();ctx.beginPath();ctx.moveTo(W*.42,-20);ctx.bezierCurveTo(W*.52,H*.24,W*.3,H*.38,W*.48,H*.55);ctx.bezierCurveTo(W*.7,H*.78,W*.56,H*.82,W*.67,H+20);ctx.lineWidth=Math.max(58,W*.105);ctx.strokeStyle='#b9aa7750';ctx.stroke();ctx.lineWidth=Math.max(46,W*.085);ctx.strokeStyle='#c2b48320';ctx.stroke();ctx.restore();
    // undergrowth and trees, fixed repeatable layout
    for(let i=0;i<43;i++){const x=((i*137.5+17)%W),y=((i*83.3+13)%H);if(y<H*.17)continue;const size=14+(i*17%25);if(Math.abs(x-W*.5)<size*1.45&&y>H*.27&&y<H*.83)continue;tree(x,y,size,i);}
    for(let i=0;i<80;i++){const x=(i*89.7+23)%W,y=(i*67.3+44)%H;if(y<H*.15)continue;const flower=i%4===0;ctx.fillStyle=flower?(i%2?'#e4d18c':'#d5a5a1')+'a0':'#b8c17b7a';ctx.beginPath();ctx.ellipse(x,y,flower?1.5:2,flower?1.2:1.6,0,0,Math.PI*2);ctx.fill();}
    for(let i=0;i<12;i++){const x=(i*173+55)%W,y=(i*119+70)%H;if(y<H*.2)continue;ctx.fillStyle='#414b3c';ctx.beginPath();ctx.ellipse(x,y,9+(i%3)*3,5+(i%2)*2,-.25,0,7);ctx.fill();ctx.fillStyle='#78806a';ctx.beginPath();ctx.ellipse(x-2,y-2,5,2,-.2,0,7);ctx.fill();}
  }
  function tree(x,y,r,i){ctx.fillStyle='#27372b';ctx.beginPath();ctx.ellipse(x+3,y+r*.48,r*.2,r*.46,.08,0,7);ctx.fill();ctx.fillStyle=i%3===0?'#334b35':i%3===1?'#40583b':'#354c37';ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(x-r*.55,y+r*.22,r*.65,0,Math.PI*2);ctx.fill();ctx.beginPath();ctx.arc(x+r*.51,y+r*.2,r*.58,0,Math.PI*2);ctx.fill();ctx.fillStyle='#76845a50';ctx.beginPath();ctx.arc(x-r*.18,y-r*.27,r*.45,0,Math.PI*2);ctx.fill();}
  function treeTop(x,y,r,color,alpha){ctx.globalAlpha=alpha;ctx.fillStyle=color;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1;}
  function drawPerson(x,y,playerPerson=false,now=0){const bob=playerPerson?Math.sin(now/180)*1.3:Math.sin(now/300)*1;ctx.save();ctx.translate(x,y+bob);ctx.fillStyle='#11170e88';ctx.beginPath();ctx.ellipse(0,13,11,5,0,0,7);ctx.fill();if(playerPerson){const color=classes[selectedClass].color;ctx.fillStyle='#353b2b';ctx.beginPath();ctx.ellipse(0,4,8,11,0,0,7);ctx.fill();ctx.fillStyle=color;ctx.beginPath();ctx.moveTo(-7,1);ctx.lineTo(-5,-6);ctx.lineTo(0,-10);ctx.lineTo(5,-6);ctx.lineTo(8,4);ctx.lineTo(5,9);ctx.lineTo(-5,9);ctx.closePath();ctx.fill();ctx.fillStyle='#d2bd8e';ctx.beginPath();ctx.arc(0,-11,5,0,7);ctx.fill();ctx.fillStyle='#526047';ctx.beginPath();ctx.moveTo(-5,-11);ctx.lineTo(0,-19);ctx.lineTo(5,-11);ctx.closePath();ctx.fill();if(selectedClass==='Swordsman'||selectedClass==='Ninja'){ctx.strokeStyle='#d9d4b8';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(6,0);ctx.lineTo(13,-11);ctx.stroke();}else if(selectedClass==='Archer'){ctx.strokeStyle='#bb9e68';ctx.lineWidth=1.5;ctx.beginPath();ctx.ellipse(9,0,3,8,.35,0,7);ctx.stroke();}else{ctx.fillStyle='#a5d6d5';ctx.shadowColor='#9ce1dc';ctx.shadowBlur=10;ctx.beginPath();ctx.arc(9,-1,3,0,7);ctx.fill();ctx.shadowBlur=0;}}
    else{ctx.fillStyle='#687350';ctx.beginPath();ctx.ellipse(0,2,12,9,0,0,7);ctx.fill();ctx.fillStyle='#859264';ctx.beginPath();ctx.arc(0,-4,9,0,7);ctx.fill();ctx.fillStyle='#4b583e';ctx.beginPath();ctx.arc(-4,-9,4,0,7);ctx.arc(5,-9,4,0,7);ctx.fill();ctx.fillStyle='#d9c996';ctx.beginPath();ctx.arc(-3,-4,1.1,0,7);ctx.arc(3,-4,1.1,0,7);ctx.fill();ctx.fillStyle='#859264';ctx.beginPath();ctx.moveTo(-4,7);ctx.lineTo(-8,12);ctx.lineTo(-3,10);ctx.fill();ctx.beginPath();ctx.moveTo(5,7);ctx.lineTo(9,11);ctx.lineTo(4,10);ctx.fill();}
    ctx.restore();}
  function drawMob(m,now){if(!m.alive)return;const selected=mobs.indexOf(m)===target;const scale=clamp(0.82+m.level*.025,.82,1.35);ctx.save();ctx.translate(m.x,m.y);ctx.scale(scale,scale);if(selected){ctx.strokeStyle='#dfca82';ctx.lineWidth=1;ctx.beginPath();ctx.ellipse(0,13,18,6,0,0,7);ctx.stroke();}drawPerson(0,0,false,now);ctx.restore();if(selected){ctx.fillStyle='#f0dfa4';ctx.font='9px DM Sans';ctx.textAlign='center';ctx.fillText(m.name,m.x,m.y-25);}}
  function draw(now=0){if(!W||!H)return;ctx.clearRect(0,0,W,H);terrain();for(const m of mobs)drawMob(m,now);drawPerson(player.x,player.y,true,now);if(attackFlash>now){ctx.strokeStyle=`rgba(241,218,148,${(attackFlash-now)/280})`;ctx.lineWidth=3;ctx.beginPath();ctx.arc(player.x,player.y,29+(attackFlash-now)/18,0,7);ctx.stroke();}drawMini();}
  function drawMini(){if(!mctx)return;const w=mini.width,h=mini.height;mctx.fillStyle='#354935';mctx.fillRect(0,0,w,h);mctx.strokeStyle='#ad9e7475';mctx.lineWidth=7;mctx.beginPath();mctx.moveTo(w*.44,-5);mctx.quadraticCurveTo(w*.65,h*.5,w*.51,h+5);mctx.stroke();for(const m of mobs){if(!m.alive)continue;mctx.fillStyle='#e3b878';mctx.beginPath();mctx.arc(m.x/W*w,m.y/H*h,2,0,7);mctx.fill();}mctx.fillStyle='#f0e2a2';mctx.beginPath();mctx.arc(player.x/W*w,player.y/H*h,3,0,7);mctx.fill();}
  function loop(now){if(!lastTime)lastTime=now;const dt=Math.min((now-lastTime)/1000,.04);lastTime=now;if(!paused){let dx=0,dy=0;if(keys.has('w')||keys.has('arrowup'))dy--;if(keys.has('s')||keys.has('arrowdown'))dy++;if(keys.has('a')||keys.has('arrowleft'))dx--;if(keys.has('d')||keys.has('arrowright'))dx++;if(dx||dy){const len=Math.hypot(dx,dy);player.x=clamp(player.x+dx/len*150*dt,16,W-16);player.y=clamp(player.y+dy/len*150*dt,H*.15,H-24);}for(let i=0;i<mobs.length;i++){let m=mobs[i];if(!m.alive){m.respawn-=dt;if(m.respawn<=0)mobs[i]=makeMob(rand(W*.18,W*.82),rand(H*.25,H*.75));continue;}const dist=Math.hypot(player.x-m.x,player.y-m.y);if(dist<175&&dist>34){m.x+=(player.x-m.x)/dist*30*dt;m.y+=(player.y-m.y)/dist*30*dt;}else if(dist<40&&now>m.attackAt){m.attackAt=now+1700;const damage=Math.max(3,Math.floor(m.level*3+rand(2,7)-player.stats[3]*.15));player.hp=Math.max(0,player.hp-damage);render();if(player.hp===0){player.hp=Math.ceil(player.maxHp*.55);player.x=W*.49;player.y=H*.65;showToast('You catch your breath at the trailhead');render();}}}if(player.hp<player.maxHp){player.hp=Math.min(player.maxHp,player.hp+dt*.75);renderVitals();}if(now>autosaveAt){save();autosaveAt=now+10000;}}
    draw(now);requestAnimationFrame(loop);}
  function renderVitals(){$('hp-text').textContent=`${Math.ceil(player.hp)} / ${player.maxHp}`;}
  function render(){const levelText=player.level>99999999?'∞':player.level.toLocaleString();$('level').textContent=levelText;$('class-name').innerHTML=`${selectedClass} <span>·</span> Level <b>${levelText}</b>`;$('class-icon').textContent=classes[selectedClass].icon;$('xp-label').textContent=`${player.xp.toLocaleString()} / ${levelXP(player.level).toLocaleString()} XP`;$('xp-bar').style.width=`${Math.min(100,player.xp/levelXP(player.level)*100)}%`;renderVitals();$('mana-text').textContent=`${Math.ceil(player.mana)} / ${player.maxMana}`;['str-stat','agi-stat','int-stat','vit-stat'].forEach((id,i)=>$(id).textContent=player.stats[i]);$('stat-points').textContent=player.statPoints;$('skill-points').textContent=player.skillPoints;$('gold-count').textContent=player.gold;$('potion-count').textContent=player.potions;$('mob-count').textContent=String(mobs.filter(m=>m.alive).length).padStart(2,'0');$('quest-progress').textContent=`${Math.min(questKills,3)} / 3`;if(player.level>=99999999){$('pvp-status').textContent='The Crucible is now open';$('pvp-progress').style.width='100%';}else{$('pvp-status').textContent='Reach ∞ to unlock PvP';$('pvp-progress').style.width=`${Math.min(99,Math.max(2,player.level/99999999*100))}%`;}
    const m=mobs[target];if(m&&m.alive){$('target-card').classList.remove('hidden');$('target-name').textContent=m.name;$('target-level').textContent=`LVL ${m.level>99999999?'∞':m.level}`;$('target-species').textContent=`${m.type} · HOSTILE`;$('target-hp-bar').style.width=`${Math.max(0,m.hp/m.maxHp*100)}%`;}else $('target-card').classList.add('hidden');renderLoot();}
  function renderLoot(){const list=$('loot-list');if(!player.items.length){list.innerHTML='<div class="empty-loot"><span>◇</span><b>Your pack is waiting</b><small>Defeat creatures to find gear</small></div>';return;}list.innerHTML=player.items.slice(0,3).map(item=>`<div class="loot-item"><span class="loot-glyph" style="color:${item.color};border-color:${item.color}66">${item.glyph}</span><span class="loot-copy"><b style="color:${item.color}">${item.name}</b><small>${item.rarity} · ${item.slot}</small></span><span class="loot-power">+${item.power}</span></div>`).join('');}
  function showToast(text){const el=$('combat-toast');el.textContent=text;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1050);}
  function gainXP(amount){player.xp+=amount;let leveled=false;while(player.xp>=levelXP(player.level)){player.xp-=levelXP(player.level);const old=player.level;player.level++;player.statPoints+=3;player.skillPoints+=5;player.maxHp+=Math.ceil(4+player.stats[3]*.25);player.hp=player.maxHp;player.maxMana+=3;player.mana=player.maxMana;leveled=true;$('old-level').textContent=old>99999999?'∞':old.toLocaleString();$('new-level').textContent=player.level>99999999?'∞':player.level.toLocaleString();}render();if(leveled){paused=true;$('level-backdrop').classList.remove('hidden');}}
  function killMob(m){m.alive=false;m.respawn=4.5;const xp=Math.floor((42+m.level*12)*(.95+Math.random()*.2));player.gold+=Math.floor(rand(3,9)*Math.sqrt(m.level));questKills++;showToast(`+${xp} XP  ·  +${Math.floor(rand(3,9))} gold`);gainXP(xp);if(questKills===3){player.xp+=60;showToast('Quest complete · +60 XP');gainXP(0);}if(Math.random()<.58){const rarityRoll=Math.random();let tier=rarityRoll<.52?0:rarityRoll<.77?1:rarityRoll<.91?2:rarityRoll<.967?3:rarityRoll<.99?4:rarityRoll<.998?5:6;const names=gear[selectedClass];const item={name:names[Math.floor(Math.random()*names.length)],rarity:rarityNames[tier],color:rarityColors[tier],slot:['Weapon','Armor','Charm'][Math.floor(Math.random()*3)],power:Math.max(1,Math.floor((m.level+1)*(tier+1)*rand(.8,1.35))),glyph:['✦','⬡','◈','✧','❖','☼','✺'][tier]};player.items.unshift(item);player.items=player.items.slice(0,20);showToast(`${item.rarity} find: ${item.name}`);}target=-1;render();save();}
  function attack(skill=false){if(paused)return;if(skill&&player.mana<12){showToast('Not enough focus');return;}let m=mobs[target];if(!m||!m.alive){let nearest=-1,dist=Infinity;mobs.forEach((v,i)=>{const d=Math.hypot(player.x-v.x,player.y-v.y);if(v.alive&&d<dist){dist=d;nearest=i;}});target=nearest;m=mobs[target];}if(!m)return;const d=Math.hypot(player.x-m.x,player.y-m.y);if(d>(skill?245:95)){showToast('Move closer to your target');return;}if(skill)player.mana-=12;const base=classes[selectedClass].damage+player.stats[0]*1.25+player.stats[2]*.5;const damage=Math.max(1,Math.floor(base*(skill?2.05:rand(.8,1.25))*(1+player.stats[1]*.015)));m.hp-=damage;attackFlash=performance.now()+250;showToast(`${skill?classes[selectedClass].skill:'Strike'}  ·  ${damage}`);if(m.hp<=0)killMob(m);render();}
  function allocate(index){if(player.statPoints<1){showToast('No stat points available');return;}player.stats[index]++;player.statPoints--;if(index===3){player.maxHp+=8;player.hp+=8;}if(index===2)player.maxMana+=4;render();save();}
  function openInfo(title,kicker,html){$('info-title').textContent=title;$('info-kicker').textContent=kicker;$('info-content').innerHTML=html;$('info-backdrop').classList.remove('hidden');}
  function save(){try{localStorage.setItem('everfall-save-v1',JSON.stringify({player,selectedClass,questKills}));$('save-status').innerHTML='PROGRESS SAVED LOCALLY <b>·</b>';}catch(e){}}
  function load(){try{const data=JSON.parse(localStorage.getItem('everfall-save-v1'));if(data&&data.player){player={...player,...data.player};selectedClass=data.selectedClass||'Swordsman';questKills=data.questKills||0;const base=classes[selectedClass];if(!data.player.maxHp){player.maxHp=base.hp;player.hp=base.hp;}if(!data.player.stats)player.stats=base.stats.slice();paused=false;$('modal-backdrop').classList.add('hidden');}}catch(e){}}
  document.querySelectorAll('.class-option').forEach(button=>button.addEventListener('click',()=>{selectedClass=button.dataset.class;document.querySelectorAll('.class-option').forEach(b=>b.classList.toggle('selected',b===button));}));
  $('begin-button').addEventListener('click',()=>{const base=classes[selectedClass];player.stats=base.stats.slice();player.maxHp=base.hp;player.hp=base.hp;player.maxMana=base.mana;player.mana=base.mana;player.x=W*.49;player.y=H*.65;paused=false;$('modal-backdrop').classList.add('hidden');render();save();});
  $('continue-button').addEventListener('click',()=>{$('level-backdrop').classList.add('hidden');paused=false;save();});
  $('attack-button').addEventListener('click',()=>attack(false));$('skill-button').addEventListener('click',()=>attack(true));$('potion-button').addEventListener('click',()=>{if(player.potions<1){showToast('No healing tonics left');return;}if(player.hp>=player.maxHp){showToast('Your vitality is full');return;}player.potions--;player.hp=Math.min(player.maxHp,player.hp+Math.floor(player.maxHp*.5));render();save();showToast('Healing tonic · vitality restored');});
  $('open-stats').addEventListener('click',()=>openInfo('Attribute points','CHARACTER','<p>You have <b>'+player.statPoints+' unspent points</b>. Choose an attribute to strengthen:</p><ul><li><b>Strength</b> — improves your physical damage.</li><li><b>Agility</b> — increases your critical chance and attack speed.</li><li><b>Intelligence</b> — strengthens spells and expands your focus.</li><li><b>Vitality</b> — increases your maximum health.</li></ul><div class="allocate-row"><button data-stat="0">+ Strength</button><button data-stat="1">+ Agility</button><button data-stat="2">+ Intelligence</button><button data-stat="3">+ Vitality</button></div>'));
  $('skills-button').addEventListener('click',()=>openInfo('Skill tree','YOUR PATH',`<p><b>${player.skillPoints} skill points available</b> · Each level grants five.</p><p><b>${classes[selectedClass].skill}</b> — spend a point to improve your signature ability.</p><p>In this frontier preview, your skill points are tracked and your active skill is ready in slot 2. Skills persist as you progress.</p>`));
  $('skill-button').addEventListener('contextmenu',e=>e.preventDefault());
  $('pvp-button').addEventListener('click',()=>openInfo('The Crucible','END-GAME','<p>Online PvP unlocks when your level reaches <b>∞ (Level 99,999,999)</b>.</p><p>At that milestone, the Crucible matchmaking queue becomes available. This preview is a local single-player prototype; online matchmaking requires a multiplayer backend.</p>'));
  $('inventory-button').addEventListener('click',()=>openInfo('Wayfarer’s pack','INVENTORY',player.items.length?'<p>'+player.items.map(i=>`<b style="color:${i.color}">${i.name}</b> — ${i.rarity} ${i.slot} (+${i.power})`).join('<br>')+'</p>':'<p>Your pack is empty. Defeat creatures to discover class-tailored equipment.</p>'));
  $('bag-button').addEventListener('click',()=>$('inventory-button').click());$('settings-button').addEventListener('click',()=>openInfo('Field journal','JOURNAL','<p><b>A Wilder Awakening</b> — defeat creatures in the wilds.</p><p>Progress: '+Math.min(questKills,3)+' / 3 · Reward: 60 XP.</p>'));
  $('help-button').addEventListener('click',()=>openInfo('How to play','FIELD GUIDE','<ul><li><b>W A S D</b> or arrow keys to explore.</li><li><b>Click a creature</b> to target it; press <b>Space</b> or use Strike.</li><li>Move close to attack. Arcane Bolt reaches farther and costs focus.</li><li>Defeat creatures to gain XP and class-tailored randomized loot.</li><li>Every level grants <b>3 attribute points</b> and <b>5 skill points</b>.</li><li>Drink a tonic with key <b>3</b> to restore health.</li></ul>'));
  $('info-close').addEventListener('click',()=>$('info-backdrop').classList.add('hidden'));$('info-done').addEventListener('click',()=>$('info-backdrop').classList.add('hidden'));$('info-backdrop').addEventListener('click',e=>{if(e.target===$('info-backdrop'))$('info-backdrop').classList.add('hidden');});
  $('info-content').addEventListener('click',e=>{const b=e.target.closest('[data-stat]');if(!b)return;allocate(+b.dataset.stat);$('info-backdrop').classList.add('hidden');});
  $('target-close').addEventListener('click',()=>{target=-1;render();});$('map-toggle').addEventListener('click',()=>{showMap=!showMap;$('map-overlay').classList.toggle('hidden',!showMap);});$('sound-toggle').addEventListener('click',e=>{e.currentTarget.classList.toggle('muted');showToast(e.currentTarget.classList.contains('muted')?'Sound muted':'Ambient sound is off in this preview');});
  canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect();const x=e.clientX-r.left,y=e.clientY-r.top;let best=-1,dist=36;mobs.forEach((m,i)=>{if(!m.alive)return;const d=Math.hypot(x-m.x,y-m.y);if(d<dist){best=i;dist=d;}});if(best>=0){target=best;render();if(!paused&&Math.hypot(player.x-mobs[target].x,player.y-mobs[target].y)<95)attack(false);}});
  window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k===' '&&!paused)attack(false);if(k==='1'&&!paused)attack(false);if(k==='2'&&!paused)attack(true);if(k==='3'&&!paused)$('potion-button').click();if(k==='i')$('bag-button').click();if(k==='j')$('settings-button').click();keys.add(k);});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));window.addEventListener('blur',()=>keys.clear());
  // Attribute shortcuts appear when the allocation panel is open.
